def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_budgets = []
    urgent_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_budgets.append(float(opp.get('budget', 0)))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    rich_opp = max(opp_budgets) if opp_budgets else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if day >= 8:
        danger += 1

    if supply <= 17:
        danger += 1

    if danger >= 5:
        base = 0.92 * DAILY_SALARY + 0.18 * highest_prev
        if highest_prev >= 150:
            base = max(base, 118.0)
        bid = min(budget, base)
        return float(max(0.0, bid))

    if danger >= 3:
        target = max(0.72 * DAILY_SALARY, min(highest_prev + 2.5, 0.95 * DAILY_SALARY + 18.0))
        if supply >= 22 and hp >= 6 and no_water_days == 0:
            target *= 0.82
        bid = min(budget, target)
        return float(max(0.0, bid))

    if highest_prev >= 170:
        if supply >= 21 and hp >= 6 and no_water_days == 0:
            return float(min(budget, 16.0))
        return float(min(budget, 54.0))

    if highest_prev >= 120:
        if supply >= 20:
            target = 24.0 + 8.0 * (1.0 - supply_pressure)
        else:
            target = 42.0
        if urgent_opp >= 2:
            target += 6.0
        return float(max(0.0, min(budget, target)))

    target = 26.0 + 18.0 * supply_pressure
    if avg_prev > 0:
        target = max(target, min(avg_prev + 1.5, 52.0))
    if rich_opp > budget * 1.8 and supply <= 18:
        target += 6.0
    if supply >= 23 and hp >= 7 and no_water_days == 0:
        target -= 8.0
    if day == 1:
        target -= 4.0

    target = max(12.0, target)
    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    max_prev = max(prev_bids) if prev_bids else 80.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)

    if day_context['supply'] < (len(alive_opponents) + 1) * WATER_REQ:
        return min(my_status['budget'], max_prev + 2.0)

    return min(my_status['budget'], max(40.0, max_prev * 0.7))
